import { useState } from 'react';
import {
  JxFormField,
  JxInput,
  JxHelperText,
  JxSelect,
  JxSelectOption,
  JxSwitch,
  JxButton,
  JxAlert,
  JxStack,
} from '@jinx-ui/react';

type Role = 'member' | 'admin' | 'viewer';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function InviteTeamForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<Role>('member');
  const [notify, setNotify] = useState(true);
  const [touched, setTouched] = useState(false);
  const [success, setSuccess] = useState(false);

  const isEmailValid = EMAIL_PATTERN.test(email);
  const showError = touched && email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid;

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) {
      return;
    }
    setSuccess(true);
  };

  return (
    <JxStack direction="column" gap="md" className="jx-container">
      {success && (
        <JxAlert
          variant="success"
          title="Приглашение отправлено"
          onClose={() => setSuccess(false)}
        >
          Пользователь {email} приглашён в команду.
        </JxAlert>
      )}

      <form onSubmit={handleSubmit} noValidate>
        <JxStack direction="column" gap="md">
          <JxFormField
            label="Email"
            required
            invalid={showError}
          >
            <JxInput
              type="email"
              name="email"
              placeholder="name@company.com"
              value={email}
              onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
                setEmail(event.target.value)
              }
              onBlur={() => setTouched(true)}
              invalid={showError}
              aria-invalid={showError}
            />
            <JxHelperText tone={showError ? 'danger' : 'neutral'}>
              {showError
                ? 'Введите корректный email-адрес'
                : 'На этот адрес придёт ссылка для присоединения к команде'}
            </JxHelperText>
          </JxFormField>

          <JxFormField label="Роль">
            <JxSelect
              name="role"
              value={role}
              onChange={(value: string) => setRole(value as Role)}
            >
              <JxSelectOption value="member">Участник</JxSelectOption>
              <JxSelectOption value="admin">Администратор</JxSelectOption>
              <JxSelectOption value="viewer">Наблюдатель</JxSelectOption>
            </JxSelect>
          </JxFormField>

          <JxSwitch
            checked={notify}
            onChange={(checked: boolean) => setNotify(checked)}
            label="Отправить уведомление на почту"
          />

          <JxButton type="submit" disabled={!canSubmit}>
            Отправить приглашение
          </JxButton>
        </JxStack>
      </form>
    </JxStack>
  );
}

